expected.referenceSolver:
def run_stage(name, fn, budget_ms, clock):
    try:
        start = clock()
        value = fn()
        dauer = clock() - start
    except Exception as exc:
        return {"status": "fehler", "grund": f"{type(exc).__name__}: {exc}", "stage": name}
    if dauer > budget_ms:
        return {"status": "timeout", "budget_ms": budget_ms, "dauer_ms": dauer, "stage": name}
    return {"status": "ok", "value": value, "dauer_ms": dauer, "stage": name}

# Ausnahme -> 'fehler' mit Typ und Meldung; Budget -> 'timeout'; sonst 'ok'.

