def starte_pipeline(stages, budget_ms, clock):
    """'ok' mit ergebnissen/dauer_ms oder 'abgebrochen' mit fehlerhafter Stage."""
    ...

expected.referenceSolver:
def starte_pipeline(stages, budget_ms, clock):
    ergebnisse = {}
    dauer_ms = {}
    berichte = {}
    for name, fn in stages:
        try:
            start = clock()
            value = fn()
            dauer = clock() - start
        except Exception as exc:
            berichte[name] = {"status": "fehler", "grund": f"{type(exc).__name__}: {exc}", "dauer_ms": 0}
            return {"status": "abgebrochen", "fehlerhafte_stage": name, "bericht": berichte}
        if dauer > budget_ms:
            berichte[name] = {"status": "timeout", "budget_ms": budget_ms, "dauer_ms": dauer}
            return {"status": "abgebrochen", "fehlerhafte_stage": name, "bericht": berichte}
        berichte[name] = {"status": "ok", "dauer_ms": dauer}
        ergebnisse[name] = value
        dauer_ms[name] = dauer
    return {"status": "ok", "ergebnisse": ergebnisse, "dauer_ms": dauer_ms}

# Lauf 1: laden dauer 5, rechnen 10, berichten 10 -> ok
# Lauf 2: rechnen wirft RuntimeError -> abgebrochen mit Grund
# Lauf 3: laden dauer 10 > 3 -> timeout-Abbruch

